            modelBuilder.Entity("Domain.Handwriting.HandwritingPracticeAttempt", b =>
                {
                    b.Property<long>("Id")
                        .HasColumnType("bigint")
                        .HasColumnName("id");

                    b.Property<string>("AlgorithmVersion")
                        .IsRequired()
                        .HasMaxLength(64)
                        .HasColumnType("character varying(64)")
                        .HasColumnName("algorithm_version");

                    b.Property<int>("CharacterCount")
                        .HasColumnType("integer")
                        .HasColumnName("character_count");

                    b.Property<DateTimeOffset>("CreatedAt")
                        .ValueGeneratedOnAdd()
                        .HasColumnType("timestamp with time zone")
                        .HasColumnName("created_at")
                        .HasDefaultValueSql("now()");

                    b.Property<long>("LearningProfileId")
                        .HasColumnType("bigint")
                        .HasColumnName("learning_profile_id");

                    b.Property<int>("MatchScore")
                        .HasColumnType("integer")
                        .HasColumnName("match_score");

                    b.Property<bool>("Passed")
                        .HasColumnType("boolean")
                        .HasColumnName("passed");

                    b.Property<string>("TargetText")
                        .IsRequired()
                        .HasMaxLength(256)
                        .HasColumnType("character varying(256)")
                        .HasColumnName("target_text");

                    b.Property<DateTimeOffset>("UpdatedAt")
                        .HasColumnType("timestamp with time zone")
                        .HasColumnName("updated_at");

                    b.Property<long>("Version")
                        .IsConcurrencyToken()
                        .HasColumnType("bigint")
                        .HasDefaultValue(1L)
                        .HasColumnName("version");

                    b.Property<long>("WritingSystemId")
                        .HasColumnType("bigint")
                        .HasColumnName("writing_system_id");

                    b.HasKey("Id");

                    b.HasIndex("WritingSystemId")
                        .HasDatabaseName("ix_handwriting_attempts_writing_system_id");

                    b.HasIndex("LearningProfileId", "Id")
                        .IsDescending(false, true)
                        .HasDatabaseName("ix_handwriting_attempts_profile_id_id");

                    b.ToTable("handwriting_practice_attempts", null, t =>
                        {
                            t.HasCheckConstraint("ck_handwriting_attempts_algorithm", "algorithm_version ~ '^[a-z][a-z0-9-]*$'");

                            t.HasCheckConstraint("ck_handwriting_attempts_characters", "character_count BETWEEN 1 AND 4");

                            t.HasCheckConstraint("ck_handwriting_attempts_immutable_state", "version = 1 AND updated_at = created_at");

                            t.HasCheckConstraint("ck_handwriting_attempts_positive_ids", "id > 0 AND learning_profile_id > 0 AND writing_system_id > 0");

                            t.HasCheckConstraint("ck_handwriting_attempts_score", "match_score BETWEEN 0 AND 100");

                            t.HasCheckConstraint("ck_handwriting_attempts_text", "target_text ~ '[^[:space:]]'");
                        });
                });

            modelBuilder.Entity("Domain.Handwriting.HandwritingPracticeCharacter", b =>
                {
                    b.Property<long>("Id")
                        .HasColumnType("bigint")
                        .HasColumnName("id");

                    b.Property<long>("AttemptId")
                        .HasColumnType("bigint")
                        .HasColumnName("attempt_id");

                    b.Property<DateTimeOffset>("CreatedAt")
                        .ValueGeneratedOnAdd()
                        .HasColumnType("timestamp with time zone")
                        .HasColumnName("created_at")
                        .HasDefaultValueSql("now()");

                    b.Property<string>("Drawing")
                        .IsRequired()
                        .HasColumnType("jsonb")
                        .HasColumnName("drawing");

                    b.Property<int>("DrawingFormatVersion")
                        .HasColumnType("integer")
                        .HasColumnName("drawing_format_version");

                    b.Property<string>("Feedback")
                        .IsRequired()
                        .HasColumnType("jsonb")
                        .HasColumnName("feedback");

                    b.Property<int>("FeedbackFormatVersion")
                        .HasColumnType("integer")
                        .HasColumnName("feedback_format_version");

                    b.Property<int>("Position")
                        .HasColumnType("integer")
                        .HasColumnName("position");

                    b.Property<long>("TemplateId")
                        .HasColumnType("bigint")
                        .HasColumnName("template_id");

                    b.Property<DateTimeOffset>("UpdatedAt")
                        .HasColumnType("timestamp with time zone")
                        .HasColumnName("updated_at");

                    b.Property<long>("Version")
                        .IsConcurrencyToken()
                        .HasColumnType("bigint")
                        .HasDefaultValue(1L)
                        .HasColumnName("version");

                    b.HasKey("Id");

                    b.HasIndex("TemplateId")
                        .HasDatabaseName("ix_handwriting_characters_template_id");

                    b.HasIndex("AttemptId", "Position")
                        .IsUnique()
                        .HasDatabaseName("ux_handwriting_characters_attempt_position");

                    b.ToTable("handwriting_practice_characters", null, t =>
                        {
                            t.HasCheckConstraint("ck_handwriting_characters_drawing", "jsonb_path_match(drawing, 'strict\n    $.type() == \"array\" && $.size() >= 0 && $.size() <= 12\n    && !exists($[*] ? (@.type() != \"array\" || @.size() < 1 || @.size() > 512))\n    && !exists($[*][*] ? (@.type() != \"object\" || ((exists(@.x)) is unknown) || ((exists(@.y)) is unknown)\n        || @.x.type() != \"number\" || @.y.type() != \"number\"\n        || @.x < 0 || @.x > 1 || @.y < 0 || @.y > 1))', '{}', true) IS TRUE\nAND jsonb_array_length(jsonb_path_query_array(drawing, 'strict $[*][*]', '{}', true)) <= 4096");

                            t.HasCheckConstraint("ck_handwriting_characters_drawing_format", "drawing_format_version = 1");

