            modelBuilder.Entity("Domain.Vocabulary.VocabularySense", b =>
                {
                    b.Property<long>("Id")
                        .HasColumnType("bigint")
                        .HasColumnName("id");

                    b.Property<string>("Code")
                        .IsRequired()
                        .HasMaxLength(64)
                        .HasColumnType("character varying(64)")
                        .HasColumnName("code");

                    b.Property<DateTimeOffset>("CreatedAt")
                        .ValueGeneratedOnAdd()
                        .HasColumnType("timestamp with time zone")
                        .HasColumnName("created_at")
                        .HasDefaultValueSql("now()");

                    b.Property<string>("PartOfSpeech")
                        .IsRequired()
                        .HasMaxLength(32)
                        .HasColumnType("character varying(32)")
                        .HasColumnName("part_of_speech");

                    b.Property<int>("SortOrder")
                        .HasColumnType("integer")
                        .HasDefaultValue(0)
                        .HasColumnName("sort_order");

                    b.Property<DateTimeOffset>("UpdatedAt")
                        .HasColumnType("timestamp with time zone")
                        .HasColumnName("updated_at");

                    b.Property<long>("Version")
                        .IsConcurrencyToken()
                        .HasColumnType("bigint")
                        .HasDefaultValue(1L)
                        .HasColumnName("version");

                    b.Property<long>("VocabularyEntryId")
                        .HasColumnType("bigint")
                        .HasColumnName("vocabulary_entry_id");

                    b.HasKey("Id");

                    b.HasIndex("VocabularyEntryId", "Code")
                        .IsUnique()
                        .HasDatabaseName("ux_vocabulary_senses_entry_id_code");

                    b.HasIndex("VocabularyEntryId", "SortOrder", "Id")
                        .HasDatabaseName("ix_vocabulary_senses_entry_id_sort_order_id");

                    b.ToTable("vocabulary_senses", null, t =>
                        {
                            t.HasCheckConstraint("ck_vocabulary_senses_code", "code ~ '^[a-z][a-z0-9-]*$'");

                            t.HasCheckConstraint("ck_vocabulary_senses_part_of_speech", "part_of_speech IN ('Noun', 'Verb', 'Adjective', 'Adverb', 'Pronoun', 'Determiner', 'Adposition', 'Conjunction', 'Particle', 'Interjection', 'Numeral', 'Auxiliary', 'Other')");

                            t.HasCheckConstraint("ck_vocabulary_senses_positive_ids", "id > 0 AND vocabulary_entry_id > 0");

                            t.HasCheckConstraint("ck_vocabulary_senses_sort_order", "sort_order >= 0");

                            t.HasCheckConstraint("ck_vocabulary_senses_timestamps", "updated_at >= created_at");

                            t.HasCheckConstraint("ck_vocabulary_senses_version", "version > 0");
                        });

