                        .IsConcurrencyToken()
                        .HasColumnType("bigint")
                        .HasDefaultValue(1L)
                        .HasColumnName("version");

                    b.Property<long>("VocabularySenseId")
                        .HasColumnType("bigint")
                        .HasColumnName("vocabulary_sense_id");

                    b.HasKey("Id");

                    b.HasIndex("VocabularySenseId", "Locale")
                        .IsUnique()
                        .HasDatabaseName("ux_vocabulary_sense_translations_sense_id_locale");

