                        {
                            t.HasCheckConstraint("ck_vocabulary_sense_translations_locale", "locale ~ '^[a-z]{2,8}(-[a-z0-9]{1,8})*$'");

                            t.HasCheckConstraint("ck_vocabulary_sense_translations_meaning", "meaning ~ '[^[:space:]]'");

                            t.HasCheckConstraint("ck_vocabulary_sense_translations_positive_ids", "id > 0 AND vocabulary_sense_id > 0");

                            t.HasCheckConstraint("ck_vocabulary_sense_translations_timestamps", "updated_at >= created_at");

                            t.HasCheckConstraint("ck_vocabulary_sense_translations_usage_note", "usage_note IS NULL OR usage_note ~ '[^[:space:]]'");

                            t.HasCheckConstraint("ck_vocabulary_sense_translations_version", "version > 0");
                        });

