            modelBuilder.Entity("Domain.WritingSystems.WritingSystemItemReading", b =>
                {
                    b.Property<long>("Id")
                        .HasColumnType("bigint")
                        .HasColumnName("id");

                    b.Property<string>("AudioUrl")
                        .HasMaxLength(1024)
                        .HasColumnType("character varying(1024)")
                        .HasColumnName("audio_url");

                    b.Property<string>("Code")
                        .IsRequired()
                        .HasMaxLength(64)
                        .HasColumnType("character varying(64)")
                        .HasColumnName("code");

                    b.Property<DateTimeOffset>("CreatedAt")
                        .ValueGeneratedOnAdd()
                        .HasColumnType("timestamp with time zone")
                        .HasColumnName("created_at")
                        .HasDefaultValueSql("now()");

                    b.Property<int>("SortOrder")
                        .HasColumnType("integer")
                        .HasDefaultValue(0)
                        .HasColumnName("sort_order");

                    b.Property<string>("Transcription")
                        .IsRequired()
                        .HasMaxLength(200)
                        .HasColumnType("character varying(200)")
                        .HasColumnName("transcription");

                    b.Property<string>("TranscriptionSystem")
                        .IsRequired()
                        .HasMaxLength(64)
                        .HasColumnType("character varying(64)")
                        .HasColumnName("transcription_system");

                    b.Property<DateTimeOffset>("UpdatedAt")
                        .HasColumnType("timestamp with time zone")
                        .HasColumnName("updated_at");

                    b.Property<long>("Version")
                        .IsConcurrencyToken()
                        .HasColumnType("bigint")
                        .HasDefaultValue(1L)
                        .HasColumnName("version");

                    b.Property<long>("WritingSystemItemId")
                        .HasColumnType("bigint")
                        .HasColumnName("writing_system_item_id");

                    b.HasKey("Id");

                    b.HasIndex("WritingSystemItemId", "Code")
                        .IsUnique()
                        .HasDatabaseName("ux_writing_system_item_readings_writing_system_item_id_code");

                    b.HasIndex("WritingSystemItemId", "SortOrder", "Id")
                        .HasDatabaseName("ix_writing_item_readings_item_id_sort_order_id");

                    b.ToTable("writing_system_item_readings", null, t =>
                        {
                            t.HasCheckConstraint("ck_writing_system_item_readings_audio_url", "audio_url IS NULL OR audio_url ~ '^https://[^/?#[:space:]@]+([/?][^#[:space:]]*)?$'");

                            t.HasCheckConstraint("ck_writing_system_item_readings_code", "code ~ '^[a-z][a-z0-9-]*$'");

                            t.HasCheckConstraint("ck_writing_system_item_readings_positive_ids", "id > 0 AND writing_system_item_id > 0");

                            t.HasCheckConstraint("ck_writing_system_item_readings_sort_order", "sort_order >= 0");

                            t.HasCheckConstraint("ck_writing_system_item_readings_timestamps", "updated_at >= created_at");

                            t.HasCheckConstraint("ck_writing_system_item_readings_transcription", "length(btrim(transcription)) > 0");

                            t.HasCheckConstraint("ck_writing_system_item_readings_transcription_system", "transcription_system ~ '^[a-z][a-z0-9-]*$'");

                            t.HasCheckConstraint("ck_writing_system_item_readings_version", "version > 0");
                        });

